": \"COUNTING\", \"max_rounds\": 3, \"is_setup_done\": 1, \"total_booths\": 15, \"counting_tables\": 5}, {\"category\": \"PS\", \"block_name\": \"Jhallara\", \"ward_no\": 13, \"ward_name_hindi\": \"Jhallara \u0935\u093e\u0930\u094d\u0921 13\", \"reservation\": \"ST\", \"status\": \"COUNTING\", \"max_rounds\": 3, \"is_setup_done\": 1, \"total_booths\": 15, \"counting_tables\": 5}, {\"category\": \"PS\", \"block_name\": \"Jhallara\", \"ward_no\": 14, \"ward_name_hindi\": \"Jhallara \u0935\u093e\u0930\u094d\u0921 14\", \"reservation\": \"ST\", \"status\": \"COUNTING\", \"max_rounds\": 3, \"is_setup_done\": 1, \"total_booths\": 15, \"counting_tables\": 5}, {\"category\": \"PS\", \"block_name\": \"Jhallara\", \"ward_no\": 15, \"ward_name_hindi\": \"Jhallara \u0935\u093e\u0930\u094d\u0921 15\", \"reservation\": \"ST\", \"status\": \"COUNTING\", \"max_rounds\": 3, \"is_setup_done\": 1, \"total_booths\": 15, \"counting_tables\": 5}], \"roundVotes\": {}};\n\n    function checkPortalLock() {\n      const unlocked = sessionStorage.getItem('salumber_portal_unlocked');\n      const overlay = document.getElementById('portalLockOverlay');\n      if (unlocked === 'true') {\n        overlay.style.display = 'none';\n      } else {\n        overlay.style.display = 'flex';\n        setTimeout(() => {\n          const inp = document.getElementById('portalPassInput');\n          if (inp) inp.focus();\n        }, 200);\n      }\n    }\n\n    function unlockPortal() {\n      const inp = (document.getElementById('portalPassInput').value || '').trim();\n      const errEl = document.getElementById('portalPassError');\n      errEl.style.display = 'none';\n\n      if (inp === 'salumber2026' || inp === 'admin2026') {\n        sessionStorage.setItem('salumber_portal_unlocked', 'true');\n        document.getElementById('portalLockOverlay').style.display = 'none';\n      } else {\n        errEl.innerText = '\u274c Invalid password! Please try again.';\n        errEl.style.display = 'block';\n      }\n    }\n\n    \n    let activeROCenter = 'ALL';\n    let autoRotateROInterval = null;\n    const roCentersList = ['Jaisamand', 'Sarada', 'Salumbar', 'Semari', 'Lasadiya', 'Geengla', 'Jhallara'];\n    let currentROIndex = 0;\n\n    function selectROCenter(roName, btnEl) {\n      activeROCenter = roName;\n      document.querySelectorAll('.ro-pill').forEach(p => p.classList.remove('active'));\n      if (btnEl) btnEl.classList.add('active');\n      renderCards();\n    }\n\n    function toggleAutoRotateRO() {\n      const btn = document.getElementById('btnAutoRotateRO');\n      if (autoRotateROInterval) {\n        clearInterval(autoRotateROInterval);\n        autoRotateROInterval = null;\n        btn.innerText = '\ud83d\udd04 Auto-Cycle Centers: OFF';\n        btn.style.background = '#ffffff';\n        btn.style.color = 'var(--text-muted)';\n      } else {\n        btn.innerText = '\ud83d\udd04 Auto-Cycle Centers: ON';\n        btn.style.background = '#eff6ff';\n        btn.style.color = '#1d4ed8';\n        startAutoRotateRO();\n      }\n    }\n\n    function startAutoRotateRO() {\n      if (autoRotateROInterval) clearInterval(autoRotateROInterval);\n      autoRotateROInterval = setInterval(() => {\n        currentROIndex = (currentROIndex + 1) % roCentersList.length;\n        const nextRO = roCentersList[currentROIndex];\n        const pills = document.querySelectorAll('.ro-pill');\n        pills.forEach(p => {\n          if (p.textContent.includes(nextRO)) p.classList.add('active');\n          else p.classList.remove('active');\n        });\n        activeROCenter = nextRO;\n        renderCards();\n      }, 15000); // cycle every 15 seconds\n    }\n\n    function toggleFullscreen() {\n      if (!document.fullscreenElement) {\n        document.documentElement.requestFullscreen().catch(() => {});\n      } else {\n        document.exitFullscreen().catch(() => {});\n      }\n    }\n\n    window.addEventListener('DOMContentLoaded', async () => {\n      startAutoRotateRO();\n      checkPortalLock();\n      populateFilterOptions();\n      await fetchMasterData();\n      initWebSocket();\n      startAutoScrollLoop();\n    });\n\n    function populateFilterOptions() {\n      const zpSel = document.getElementById('zpWardFilter');\n      for (let i = 1; i <= 21; i++) {\n        const opt = document.createElement('option');\n        opt.value = i;\n        opt.textContent = `Ward ${i}`;\n        zpSel.appendChild(opt);\n      }\n    }\n\n    function onPsBlockFilterChanged() {\n      const blk = document.getElementById('psBlockFilter').value;\n      const psWSel = document.getElementById('psWardFilter');\n      psWSel.innerHTML = '<option value=\"ALL\">All Wards</option>';\n      if (blk !== 'ALL') {\n        for (let i = 1; i <= 15; i++) {\n          const opt = document.createElement('option');\n          opt.value = i;\n          opt.textContent = `Ward ${i}`;\n          psWSel.appendChild(opt);\n        }\n      }\n      renderCards();\n    }\n\n    async function fetchMasterData() {\n      try {\n        const resp = await fetch('/api/all_candidates_master');\n        if (resp.ok) {\n          masterData = await resp.json();\n        } else {\n          masterData = EMBEDDED_MASTER;\n        }\n      } catch (e) {\n        masterData = EMBEDDED_MASTER;\n      }\n      renderCards();\n      updateSummaryTallies();\n    }\n\n    // WebSocket\n    function initWebSocket() {\n      const loc = window.location;\n      const wsUrl = (loc.protocol === 'https:' ? 'wss://' : 'ws://') + loc.host + '/ws';\n      const ws = new WebSocket(wsUrl);\n\n      ws.onmessage = (event) => {\n        try {\n          const data = JSON.parse(event.data);\n          if (data.type === 'INITIAL_STATE' || data.type === 'FULL_UPDATE' || data.type === 'ROUND_UPDATE') {\n            fetchMasterData();\n          }\n        } catch (e) {}\n      };\n\n      ws.onclose = () => {\n        setTimeout(initWebSocket, 3000);\n      };\n    }\n\n    // Render Cards\n    function renderCards() {\n      const zpContainer = document.getElementById('zpCardsContainer');\n      const psContainer = document.getElementById('psCardsContainer');\n\n      const zpFilter = document.getElementById('zpWardFilter') ? document.getElementById('zpWardFilter').value : 'ALL';\n\n      // Render ZP\n      const zpWards = masterData.wards.filter(w => w.category === 'ZP' && (zpFilter === 'ALL' || w.ward_no == zpFilter));\n      zpWards.sort((a, b) => a.ward_no - b.ward_no);\n\n      zpContainer.innerHTML = '';\n      zpWards.forEach(w => {\n        zpContainer.appendChild(createWardCardElement(w));\n      });\n\n      // Render PS\n      const psWards = masterData.wards.filter(w => {\n        if (w.category !== 'PS') return false;\n        if (activeROCenter !== 'ALL' && w.block_name !== activeROCenter) return false;\n        return true;\n      });\n      psWards.sort((a, b) => a.block_name.localeCompare(b.block_name) || a.ward_no - b.ward_no);\n\n      psContainer.innerHTML = '';\n      psWards.forEach(w => {\n        psContainer.appendChild(createWardCardElement(w));\n      });\n    }\n\n    function createWardCardElement(ward) {\n      const isDeclared = ward.status === 'DECLARED';\n      const cands = masterData.candidates.filter(c => c.category === ward.category && c.block_name === ward.block_name && c.ward_no === ward.ward_no);\n\n      // Compute votes\n      const roundsSet = new Set();\n      const candTotals = cands.map(c => {\n        let sum = 0;\n        let lastRoundVotes = 0;\n        const vObj = masterData.roundVotes[c.id] || {};\n        for (const [rKey, count] of Object.entries(vObj)) {\n          const c = count || 0;\n          if (c > 0 || rKey.startsWith('R') || rKey.startsWith('B')) {\n            sum += c;\n            roundsSet.add(rKey);\n            lastRoundVotes = c;\n          }\n        }\n        return { ...c, totalVotes: sum, lastRoundVotes };\n      });\n\n      candTotals.sort((a, b) => b.totalVotes - a.totalVotes);\n\n      const hasVotes = candTotals.some(c => c.totalVotes > 0);\n      const isCounting = hasVotes && !isDeclared;\n      const statusKey = isDeclared ? 'DECLARED' : (isCounting ? 'COUNTING' : 'PENDING');\n      const statusLabel = isDeclared ? 'WINNER DECLARED' : (isCounting ? `ROUND ${roundsSet.size} OF ${ward.max_rounds}` : 'AWAITING VOTES');\n\n      const card = document.createElement('div');\n      card.className = `ward-card ${isDeclared ? 'declared' : (isCounting ? 'counting' : '')}`;\n\n      const leader = candTotals[0];\n      const runnerUp = candTotals[1];\n      const isTie = hasVotes && runnerUp && (leader.totalVotes === runnerUp.totalVotes);\n      const margin = isTie ? 0 : (leader && runnerUp ? (leader.totalVotes - runnerUp.totalVotes) : (leader?.totalVotes || 0));\n\n      let leaderHtml = '';\n      if (isDeclared && leader && leader.totalVotes > 0) {\n        leaderHtml = `\n          <div class=\"leader-strip declared-winner\">\n            <span>\ud83c\udfc6 <strong>${leader.name_hindi}</strong> (${leader.party || 'IND'}) WON</span>\n            <span>${margin > 0 ? `Margin: +${margin} votes` : 'Decided by Draw of Lots (Lottery)'}</span>\n          </div>\n        `;\n      } else if (isTie) {\n        leaderHtml = `\n          <div class=\"leader-strip\" style=\"background:#fffbeb; border-color:#f59e0b; color:#b45309;\">\n            <span>\u2696\ufe0f <strong>TIED: ${leader.name_hindi} & ${runnerUp.name_hindi}</strong></span>\n            <span>Equal: ${leader.totalVotes} votes each</span>\n          </div>\n        `;\n      } else if (isCounting && leader && leader.totalVotes > 0) {\n        leaderHtml = `\n          <div class=\"leader-strip\">\n            <span>\ud83d\udfe2 <strong>${leader.name_hindi}</strong> (${leader.party || 'IND'}) Leading</span>\n            <span>Margin: +${margin} votes</span>\n          </div>\n        `;\n      }\n\n      let rowsHtml = '';\n      if (candTotals.length === 0) {\n        rowsHtml = `<tr><td colspan=\"4\" style=\"text-align:center; color:var(--text-dim); padding:10px;\">Contestants awaiting finalization</td></tr>`;\n      } else {\n        candTotals.forEach((c, idx) => {\n          const isLeader = !isTie && idx === 0 && c.totalVotes > 0;\n          const isTied = isTie && (c.totalVotes === leader.totalVotes);\n          rowsHtml += `\n            <tr class=\"${isLeader ? 'row-leader' : (isTied ? 'row-tied' : '')}\" style=\"${isTied ? 'background:#fef3c7;' : ''}\">\n              <td style=\"font-weight:700; font-family:'Rajdhani',sans-serif; width:30px;\">#${c.ballot_no || idx+1}</td>\n              <td style=\"font-weight:${isLeader ? '800' : '600'};\">${c.name_hindi}</td>\n              <td style=\"width:60px;\"><span class=\"party-tag pt-${c.party || 'IND'}\">${c.party || 'IND'}</span></td>\n              <td style=\"text-align:right; font-family:'Rajdhani',sans-serif; font-size:15px; font-weight:800; color:${isLeader ? 'var(--primary)' : 'inherit'}; width:80px;\">${c.totalVotes}</td>\n            </tr>\n          `;\n        });\n      }\n\n      let displayName = ward.category === 'ZP' ? `ZP Ward ${ward.ward_no}` : `${ward.block_name} - Ward ${ward.ward_no}`;\n      let roBreakdownHtml = '';\n      if (ward.category === 'ZP') {\n        if (ward.ward_no === 1) {\n          roBreakdownHtml = '<div style=\"font-size:10px; color:#0369a1; background:#e0f2fe; padding:2px 8px; border-radius:4px; margin-top:2px; font-weight:700;\">\ud83c\udfdb\ufe0f Multi-Center: Jaisamand RO (29 Booths) + Sarada RO (3 Booths)</div>';\n        }\n      }\n\n      card.innerHTML = `\n        <div class=\"ward-card-head\">\n          <div class=\"ward-name\">\n            <span>${ward.category === 'ZP' ? '\ud83c\udfdb\ufe0f' : '\ud83c\udfd8\ufe0f'}</span>\n            <span>${displayName}</span>\n            <span style=\"font-size:10px; color:var(--text-dim); font-weight:700; background:#f1f5f9; padding:1px 5px; border-radius:3px;\">${ward.reservation || 'GEN'}</span>\n          </div>\n          <span class=\"status-badge status-${statusKey}\">${statusLabel}</span>\n        </div>\n        ${roBreakdownHtml}\n        ${leaderHtml}\n        <table class=\"ward-table\">\n          <thead>\n            <tr>\n              <th>#</th>\n              <th>Candidate</th>\n              <th>Party</th>\n              <th style=\"text-align:right;\">Votes</th>\n            </tr>\n          </thead>\n          <tbody>\n            ${rowsHtml}\n          </tbody>\n        </table>\n      `;\n\n      return card;\n    }\n\n    // Tally update\n    function updateSummaryTallies() {\n      const tally = {\n        ZP: { BJP: 0, INC: 0, BAP: 0, IND: 0 },\n        PS: { BJP: 0, INC: 0, BAP: 0, IND: 0 }\n      };\n\n      masterData.wards.forEach(w => {\n        const cands = masterData.candidates.filter(c => c.category === w.category && c.block_name === w.block_name && c.ward_no === w.ward_no);\n        const totals = cands.map(c => {\n          let sum = 0;\n          const vObj = masterData.roundVotes[c.id] || {};\n          for (const [r, cnt] of Object.entries(vObj)) sum += (cnt || 0);\n          return { ...c, sum };\n        });\n        totals.sort((a, b) => b.sum - a.sum);\n        if (totals.length > 0 && totals[0].sum > 0) {\n          const topParty = totals[0].party || 'IND';\n          if (tally[w.category][topParty] !== undefined) {\n            tally[w.category][topParty]++;\n          } else {\n            tally[w.category].IND++;\n          }\n        }\n      });\n\n      document.getElementById('zpTallyBJP').innerText = `BJP: ${tally.ZP.BJP}`;\n      document.getElementById('zpTallyINC').innerText = `INC: ${tally.ZP.INC}`;\n      document.getElementById('zpTallyBAP').innerText = `BAP: ${tally.ZP.BAP}`;\n      document.getElementById('zpTallyIND').innerText = `IND: ${tally.ZP.IND}`;\n\n      document.getElementById('psTallyBJP').innerText = `BJP: ${tally.PS.BJP}`;\n      document.getElementById('psTallyINC').innerText = `INC: ${tally.PS.INC}`;\n      document.getElementById('psTallyBAP').innerText = `BAP: ${tally.PS.BAP}`;\n      document.getElementById('psTallyIND').innerText = `IND: ${tally.PS.IND}`;\n    }\n\n    // Auto-Scroll Loop\n    function toggleScroll(col) {\n      if (col === 'zp') {\n        zpAutoScroll = !zpAutoScroll;\n        document.getElementById('btnZpScroll').innerText = zpAutoScroll ? '\u23f8 Pause Scroll' : '\u25b6 Resume Scroll';\n      } else {\n        psAutoScroll = !psAutoScroll;\n        document.getElementById('btnPsScroll').innerText = psAutoScroll ? '\u23f8 Pause Scroll' : '\u25b6 Resume Scroll';\n      }\n    }\n\n    function startAutoScrollLoop() {\n      const zpEl = document.getElementById('zpCardsContainer');\n      const psEl = document.getElementById('psCardsContainer');\n\n      setInterval(() => {\n        if (zpAutoScroll && zpEl) {\n          if (zpEl.scrollTop + zpEl.clientHeight >= zpEl.scrollHeight - 10) {\n            zpEl.scrollTop = 0;\n          } else {\n            zpEl.scrollTop += 1.2;\n          }\n        }\n      }, 50);\n\n      setInterval(() => {\n        if (psAutoScroll && psEl) {\n          if (psEl.scrollTop + psEl.clientHeight >= psEl.scrollHeight - 10) {\n            psEl.scrollTop = 0;\n          } else {\n            psEl.scrollTop += 1.2;\n          }\n        }\n      }, 50);\n    }\n  </script>\n</body>\n</html>\n";
const ENTRY_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Salumber Elections 2026 - Operator Console</title>\n  \n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Rajdhani:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    /* ==========================================================================\n       SUPER-SIMPLE LIGHT OPERATOR CONSOLE (SALUMBER ELECTIONS 2026)\n       Direct Booth & Round Entry \u2022 Auto-Mapped Wards \u2022 Zero Confusion\n       ========================================================================== */\n    :root {\n      --bg-page: #f1f5f9;\n      --bg-surface: #ffffff;\n      --bg-card: #ffffff;\n      --bg-subtle: #f8fafc;\n      --border-main: #cbd5e1;\n      --border-subtle: #e2e8f0;\n      \n      --text-main: #0f172a;\n      --text-muted: #475569;\n      --text-dim: #64748b;\n      \n      --primary: #0284c7;\n      --primary-hover: #0369a1;\n      --primary-subtle: #e0f2fe;\n      \n      --success: #15803d;\n      --success-subtle: #dcfce7;\n      \n      --warning: #b45309;\n      --warning-subtle: #fef3c7;\n      \n      --danger: #b91c1c;\n      --danger-subtle: #fee2e2;\n\n      --party-bjp: #c2410c;\n      --party-bjp-bg: #fff7ed;\n      --party-inc: #0369a1;\n      --party-inc-bg: #eff6ff;\n      --party-bap: #a16207;\n      --party-bap-bg: #fefce8;\n      --party-ind: #475569;\n      --party-ind-bg: #f1f5f9;\n\n      --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n      --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);\n      --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.05);\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n      background-color: var(--bg-page);\n      color: var(--text-main);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      padding: 16px 12px 40px;\n    }\n\n    .container {\n      width: 100%;\n      max-width: 860px;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n    }\n\n    /* HEADER */\n    .header-card {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-main);\n      border-radius: 12px;\n      padding: 14px 20px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      box-shadow: var(--shadow-sm);\n    }\n\n    .header-left h1 {\n      font-size: 17px;\n      font-weight: 800;\n      color: var(--text-main);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .header-left p {\n      font-size: 12px;\n      color: var(--text-muted);\n      margin-top: 2px;\n      font-weight: 500;\n    }\n\n    .header-actions {\n      display: flex;\n      gap: 8px;\n      align-items: center;\n    }\n\n    .btn {\n      padding: 8px 14px;\n      font-size: 12px;\n      font-weight: 700;\n      border-radius: 8px;\n      border: none;\n      cursor: pointer;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      transition: all 0.15s ease-in-out;\n      text-decoration: none;\n    }\n\n    .btn-primary { background: var(--primary); color: #ffffff; }\n    .btn-primary:hover { background: var(--primary-hover); }\n\n    .btn-outline {\n      background: #ffffff;\n      color: var(--text-main);\n      border: 1px solid var(--border-main);\n    }\n    .btn-outline:hover { background: var(--bg-subtle); border-color: var(--text-dim); }\n\n    .btn-success { background: var(--success); color: #ffffff; }\n    .btn-success:hover { background: #166534; }\n\n    .btn-danger { background: var(--danger); color: #ffffff; }\n    .btn-danger:hover { background: #991b1b; }\n\n    /* 3 NAVIGATION TABS */\n    .nav-tabs {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 6px;\n      background: #e2e8f0;\n      padding: 5px;\n      border-radius: 10px;\n      border: 1px solid var(--border-main);\n    }\n\n    .nav-tab-btn {\n      padding: 11px 10px;\n      font-size: 13px;\n      font-weight: 700;\n      border: none;\n      border-radius: 7px;\n      background: transparent;\n      color: var(--text-muted);\n      cursor: pointer;\n      text-align: center;\n      transition: all 0.15s;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n    }\n\n    .nav-tab-btn.active {\n      background: #ffffff;\n      color: var(--primary);\n      box-shadow: var(--shadow-sm);\n    }\n\n    /* CARD CONTAINER */\n    .card {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-subtle);\n      border-radius: 12px;\n      padding: 20px;\n      box-shadow: var(--shadow-sm);\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n    }\n\n    .card-head {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      border-bottom: 1px solid var(--border-subtle);\n      padding-bottom: 12px;\n    }\n\n    .card-title {\n      font-size: 15px;\n      font-weight: 800;\n      color: var(--text-main);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 4px;\n      font-size: 11px;\n      font-weight: 700;\n      padding: 3px 8px;\n      border-radius: 6px;\n    }\n\n    .badge-success { background: var(--success-subtle); color: var(--success); }\n    .badge-warning { background: var(--warning-subtle); color: var(--warning); }\n    .badge-primary { background: var(--primary-subtle); color: var(--primary); }\n\n    /* FORM GRID */\n    .form-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n      gap: 12px;\n    }\n\n    .form-group {\n      display: flex;\n      flex-direction: column;\n      gap: 5px;\n    }\n\n    .form-label {\n      font-size: 11px;\n      font-weight: 700;\n      color: var(--text-muted);\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n    }\n\n    .form-select, .form-input {\n      background: #ffffff;\n      border: 1px solid var(--border-main);\n      border-radius: 8px;\n      padding: 9px 12px;\n      font-size: 13px;\n      font-weight: 600;\n      color: var(--text-main);\n      outline: none;\n      transition: all 0.15s;\n    }\n\n    .form-select:focus, .form-input:focus {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.15);\n    }\n\n    /* ENTRY MODE TOGGLE */\n    .mode-toggle-bar {\n      display: flex;\n      gap: 12px;\n      background: var(--bg-subtle);\n      border: 1px solid var(--border-subtle);\n      padding: 8px 14px;\n      border-radius: 8px;\n      align-items: center;\n    }\n\n    .mode-radio-label {\n      font-size: 13px;\n      font-weight: 700;\n      color: var(--text-main);\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      cursor: pointer;\n    }\n\n    /* BOOTH INFO BANNER */\n    .booth-info-banner {\n      background: #eff6ff;\n      border: 1px solid #bfdbfe;\n      border-radius: 8px;\n      padding: 10px 14px;\n      font-size: 13px;\n      font-weight: 700;\n      color: #1e40af;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n\n    /* TABLE */\n    .table-container {\n      overflow-x: auto;\n      border: 1px solid var(--border-subtle);\n      border-radius: 8px;\n    }\n\n    .data-table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 13px;\n      text-align: left;\n    }\n\n    .data-table th {\n      background: var(--bg-subtle);\n      color: var(--text-muted);\n      font-size: 11px;\n      font-weight: 700;\n      text-transform: uppercase;\n      padding: 10px 14px;\n      border-bottom: 1px solid var(--border-subtle);\n      letter-spacing: 0.5px;\n    }\n\n    .data-table td {\n      padding: 11px 14px;\n      border-bottom: 1px solid var(--border-subtle);\n      vertical-align: middle;\n      color: var(--text-main);\n    }\n\n    .data-table tbody tr:hover { background: #f8fafc; }\n\n    /* PARTY PILLS */\n    .party-pill {\n      display: inline-block;\n      padding: 3px 8px;\n      border-radius: 6px;\n      font-size: 11px;\n      font-weight: 800;\n      font-family: 'Rajdhani', sans-serif;\n    }\n\n    .party-BJP { background: var(--party-bjp-bg); color: var(--party-bjp); border: 1px solid #fed7aa; }\n    .party-INC { background: var(--party-inc-bg); color: var(--party-inc); border: 1px solid #bfdbfe; }\n    .party-BAP { background: var(--party-bap-bg); color: var(--party-bap); border: 1px solid #fef08a; }\n    .party-IND { background: var(--party-ind-bg); color: var(--party-ind); border: 1px solid #cbd5e1; }\n\n    /* VOTE INPUT */\n    .vote-input {\n      width: 110px;\n      background: #ffffff;\n      border: 2px solid var(--border-main);\n      border-radius: 6px;\n      padding: 8px 10px;\n      font-family: 'Rajdhani', sans-serif;\n      font-size: 18px;\n      font-weight: 800;\n      color: var(--text-main);\n      text-align: right;\n      outline: none;\n    }\n\n    .vote-input:focus {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.2);\n    }\n\n    /* AUTH MODAL */\n    .modal-overlay {\n      position: fixed;\n      top: 0; left: 0; right: 0; bottom: 0;\n      background: rgba(15, 23, 42, 0.6);\n      backdrop-filter: blur(4px);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      z-index: 9999;\n    }\n\n    .modal-card {\n      background: #ffffff;\n      border-radius: 14px;\n      padding: 28px;\n      width: 100%;\n      max-width: 440px;\n      box-shadow: var(--shadow-lg);\n      border: 1px solid var(--border-main);\n      display: flex;\n      flex-direction: column;\n      gap: 18px;\n    }\n\n    #toast {\n      position: fixed;\n      bottom: 24px;\n      right: 24px;\n      padding: 12px 20px;\n      background: #0f172a;\n      color: #ffffff;\n      font-size: 13px;\n      font-weight: 700;\n      border-radius: 8px;\n      box-shadow: var(--shadow-lg);\n      display: none;\n      z-index: 10000;\n    }\n  </style>\n</head>\n<body>\n\n  <!-- AUTHENTICATION MODAL -->\n  <div id=\"authModal\" class=\"modal-overlay\" style=\"display:none;\">\n    <div class=\"modal-card\">\n      <div style=\"text-align:center;\">\n        <div style=\"font-size:38px; margin-bottom:8px;\">\ud83d\udd12</div>\n        <h2 style=\"font-size:17px; font-weight:800; color:#0f172a;\">Operator Console Security</h2>\n        <p style=\"font-size:12px; color:var(--text-muted); margin-top:4px;\">\n          Salumber Panchayati Raj Elections 2026<br>Please enter access password to manage counting data.\n        </p>\n      </div>\n\n      <div class=\"form-group\">\n        <label class=\"form-label\">Access Password</label>\n        <input type=\"password\" id=\"loginPassword\" class=\"form-input\" placeholder=\"Enter access password\" onkeydown=\"if(event.key==='Enter') submitLogin()\">\n      </div>\n\n      <button onclick=\"submitLogin()\" class=\"btn btn-primary\" style=\"padding:11px; justify-content:center; font-size:13px;\">\n        \ud83d\udd13 Sign In & Access Console\n      </button>\n\n      <div id=\"authError\" style=\"font-size:12px; color:var(--danger); text-align:center; display:none; font-weight:700;\"></div>\n    </div>\n  </div>\n\n  <div class=\"container\">\n    \n    <!-- HEADER -->\n    <header class=\"header-card\">\n      <div class=\"header-left\">\n        <h1><span>\ud83c\udfdb\ufe0f</span> Salumber District Elections 2026</h1>\n        <p>Live Election Operator Console \u2022 Direct Booth & Round Vote Entry</p>\n      </div>\n\n      <div class=\"header-actions\">\n        <button onclick=\"resetTestingData()\" class=\"btn btn-outline\" style=\"color:#b91c1c; border-color:#fca5a5; background:#fff1f2; font-weight:700;\">\n          \ud83e\uddf9 Reset Data (Test)\n        </button>\n        <a href=\"/\" target=\"_blank\" class=\"btn btn-outline\">\ud83d\udcfa Open TV Display</a>\n        <button onclick=\"logout()\" class=\"btn btn-outline\" style=\"color:var(--danger); border-color:#fca5a5;\">\ud83d\udd12 Lock</button>\n      </div>\n    </header>\n\n    <!-- 3 SIMPLE TABS -->\n    <nav class=\"nav-tabs\">\n      <button id=\"tabBtnEntry\" class=\"nav-tab-btn active\" onclick=\"switchNavTab('entry')\">\n        \ud83d\uddf3\ufe0f Direct Vote Entry\n      </button>\n      <button id=\"tabBtnDeclare\" class=\"nav-tab-btn\" onclick=\"switchNavTab('declare')\">\n        \ud83c\udfc6 Declare Ward Winner\n      </button>\n      <button id=\"tabBtnContestants\" class=\"nav-tab-btn\" onclick=\"switchNavTab('contestants')\">\n        \ud83d\udc65 Contestants Manager\n      </button>\n    </nav>\n\n    <!-- =====================================================================\n         TAB 1: DIRECT VOTE ENTRY (BOOTH-WISE OR ROUND-WISE)\n         ===================================================================== -->\n    <section id=\"panelEntry\" class=\"card\">\n      <div class=\"card-head\">\n        <div class=\"card-title\">\n          <span>\ud83d\uddf3\ufe0f</span> Direct Vote Entry Console\n        </div>\n        <div id=\"entryStatusBadge\" class=\"badge badge-primary\">\n          Ready for Entry\n        </div>\n      </div>\n\n      <!-- Scope Selection -->\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Category</label>\n          <select id=\"entryCategory\" class=\"form-select\" onchange=\"onCategoryChanged()\">\n            <option value=\"PS\">Panchayat Samiti (7 Blocks)</option>\n            <option value=\"ZP\">Zilla Parishad (21 Wards)</option>\n          </select>\n        </div>\n\n        <div class=\"form-group\" id=\"blockSelectGroup\">\n          <label class=\"form-label\">Panchayat Samiti Block</label>\n          <select id=\"entryBlock\" class=\"form-select\" onchange=\"onBlockChanged()\">\n            <option value=\"Semari\">Semari (69 Booths)</option>\n            <option value=\"Salumbar\">Salumbar (77 Booths)</option>\n            <option value=\"Lasadiya\">Lasadiya (73 Booths)</option>\n            <option value=\"Geengla\">Geengla (68 Booths)</option>\n            <option value=\"Jaisamand\">Jaisamand (84 Booths)</option>\n            <option value=\"Sarada\">Sarada (78 Booths)</option>\n            <option value=\"Jhallara\">Jhallara (83 Booths)</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- Entry Mode Radio Toggle (Hidden for clean Polling Station workflow) -->\n      <div class=\"mode-toggle-bar\" style=\"display:none;\">\n        <span style=\"font-size:12px; font-weight:800; color:var(--text-muted); text-transform:uppercase;\">Entry Method:</span>\n        <label class=\"mode-radio-label\">\n          <input type=\"radio\" name=\"entryMode\" value=\"booth\" checked onchange=\"toggleEntryMode('booth')\">\n          <span>\ud83d\udccd By Polling Station / Booth #</span>\n        </label>\n      </div>\n\n      <!-- Polling Station / Booth Entry -->\n      <div id=\"boothSelectorBox\" class=\"form-grid\" style=\"display:grid;\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Polling Station / Booth #</label>\n          <div style=\"display:flex; gap:8px;\">\n            <input type=\"number\" id=\"inputBoothNo\" class=\"form-input\" placeholder=\"Enter Booth # (e.g. 1)\" min=\"1\" max=\"150\" value=\"1\" oninput=\"onBoothInputChanged()\" style=\"width:130px; font-size:16px; font-weight:800;\">\n            <select id=\"selectBoothDropdown\" class=\"form-select\" style=\"flex:1;\" onchange=\"onBoothDropdownChanged()\"></select>\n          </div>\n        </div>\n      </div>\n\n      <!-- Sub-Selector B: Ward & Round Entry -->\n      <div id=\"roundSelectorBox\" class=\"form-grid\" style=\"display:none !important;\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Select Ward</label>\n          <select id=\"entryWard\" class=\"form-select\" onchange=\"onWardRoundChanged()\"></select>\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Select Counting Round</label>\n          <select id=\"entryRound\" class=\"form-select\" onchange=\"onWardRoundChanged()\">\n            <option value=\"R1\">Round 1</option>\n            <option value=\"R2\">Round 2</option>\n            <option value=\"R3\">Round 3</option>\n            <option value=\"R4\">Round 4</option>\n            <option value=\"R5\">Round 5</option>\n            <option value=\"R6\">Round 6</option>\n            <option value=\"R7\">Round 7</option>\n            <option value=\"R8\">Round 8</option>\n            <option value=\"R9\">Round 9</option>\n            <option value=\"R10\">Round 10</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- Live Auto-Mapped Details Banner -->\n      <div id=\"boothInfoBanner\" class=\"booth-info-banner\">\n        <div id=\"boothInfoText\">\ud83d\udccd Loading Polling Station...</div>\n        <div id=\"boothWardBadge\" class=\"badge badge-primary\">Ward -</div>\n      </div>\n\n      <!-- Candidate Vote Entry Table -->\n      <div class=\"table-container\">\n        <table class=\"data-table\">\n          <thead>\n            <tr>\n              <th style=\"width:60px;\">Ballot #</th>\n              <th>Candidate Name</th>\n              <th>Party</th>\n              <th style=\"width:140px; text-align:right;\">Votes (This Slip)</th>\n              <th style=\"width:110px; text-align:right;\">Prev. Total</th>\n              <th style=\"width:120px; text-align:right;\">Cumulative</th>\n            </tr>\n          </thead>\n          <tbody id=\"candidatesTableBody\"></tbody>\n        </table>\n      </div>\n\n      <!-- Save & Next Buttons -->\n      <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n        <button onclick=\"clearCurrentInputs()\" class=\"btn btn-outline\" style=\"color:var(--text-dim);\">\n          \u2715 Clear Current Inputs\n        </button>\n\n        <button id=\"btnSaveVotes\" onclick=\"submitVotes()\" class=\"btn btn-success\" style=\"padding:12px 28px; font-size:14px;\">\n          \ud83d\udcbe SAVE BOOTH VOTES\n        </button>\n      </div>\n    </section>\n\n    <!-- =====================================================================\n         TAB 2: DECLARE WARD WINNER (LIVE STANDINGS & FINALIZATION)\n         ===================================================================== -->\n    <section id=\"panelDeclare\" class=\"card\" style=\"display:none;\">\n      <div class=\"card-head\">\n        <div class=\"card-title\">\n          <span>\ud83c\udfc6</span> Official Ward Winner Declaration & Status\n        </div>\n        <span class=\"badge badge-primary\">Final Declaration Action</span>\n      </div>\n\n      <p style=\"font-size:12px; color:var(--text-muted);\">\n        Review counted booths and vote standings. When all polling stations for a ward are counted, click <strong>Declare Ward Winner</strong> to finalize.\n      </p>\n\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Category</label>\n          <select id=\"declareCategory\" class=\"form-select\" onchange=\"onDeclareScopeChanged()\">\n            <option value=\"PS\">Panchayat Samiti</option>\n            <option value=\"ZP\">Zilla Parishad</option>\n          </select>\n        </div>\n\n        <div class=\"form-group\" id=\"declareBlockGroup\">\n          <label class=\"form-label\">Block</label>\n          <select id=\"declareBlock\" class=\"form-select\" onchange=\"onDeclareScopeChanged()\">\n            <option value=\"Semari\">Semari</option>\n            <option value=\"Salumbar\">Salumbar</option>\n            <option value=\"Lasadiya\">Lasadiya</option>\n            <option value=\"Geengla\">Geengla</option>\n            <option value=\"Jaisamand\">Jaisamand</option>\n            <option value=\"Sarada\">Sarada</option>\n            <option value=\"Jhallara\">Jhallara</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- Wards Standings Table -->\n      <div class=\"table-container\">\n        <table class=\"data-table\">\n          <thead>\n            <tr>\n              <th style=\"width:70px;\">Ward #</th>\n              <th>Leading Candidate</th>\n              <th>Party</th>\n              <th style=\"text-align:right;\">Votes</th>\n              <th style=\"text-align:right;\">Lead Margin</th>\n              <th style=\"text-align:center;\">Status</th>\n              <th style=\"width:140px; text-align:center;\">Action</th>\n            </tr>\n          </thead>\n          <tbody id=\"declareWardsTableBody\"></tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- =====================================================================\n         TAB 3: CONTESTANTS MANAGER\n         ===================================================================== -->\n    <section id=\"panelContestants\" class=\"card\" style=\"display:none;\">\n      <div class=\"card-head\">\n        <div class=\"card-title\">\n          <span>\ud83d\udc65</span> Contestants Management\n        </div>\n        <span class=\"badge badge-success\">For Pending Blocks</span>\n      </div>\n\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Category</label>\n          <select id=\"manageCategory\" class=\"form-select\" onchange=\"loadManageBlockContestants()\">\n            <option value=\"PS\">Panchayat Samiti</option>\n            <option value=\"ZP\">Zilla Parishad</option>\n          </select>\n        </div>\n\n        <div class=\"form-group\" id=\"manageBlockGroup\">\n          <label class=\"form-label\">Block</label>\n          <select id=\"manageBlock\" class=\"form-select\" onchange=\"loadManageBlockContestants()\">\n            <option value=\"Jhallara\">Jhallara</option>\n            <option value=\"Sarada\">Sarada</option>\n            <option value=\"Jaisamand\">Jaisamand</option>\n            <option value=\"Semari\">Semari</option>\n            <option value=\"Salumbar\">Salumbar</option>\n            <option value=\"Lasadiya\">Lasadiya</option>\n            <option value=\"Geengla\">Geengla</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- Bulk Import -->\n      <div style=\"background:#f8fafc; border:1px solid var(--border-subtle); border-radius:10px; padding:14px; display:flex; flex-direction:column; gap:10px;\">\n        <div style=\"font-size:13px; font-weight:800; color:var(--primary);\">\n          \ud83d\udccb Bulk Import from Excel / Google Sheets\n        </div>\n        <div style=\"font-size:12px; color:var(--text-muted);\">\n          Paste rows from Form 5 / RO nomination list. Format: <code>Ward No, Candidate Name, Party, [Optional Ballot No]</code>\n        </div>\n        <textarea id=\"bulkImportText\" class=\"form-input\" style=\"height:100px; font-family:monospace; font-size:12px;\" placeholder=\"Example:\n1, Ramesh Patel, BJP, 1\n1, Suresh Meena, INC, 2\n1, Anita Sharma, IND, 3\n2, Vikram Singh, BJP, 1\"></textarea>\n        <button onclick=\"submitBulkImport()\" class=\"btn btn-primary\" style=\"align-self:flex-start; padding:9px 16px;\">\n          \ud83d\ude80 Import Contestants\n        </button>\n      </div>\n\n      <!-- Candidate List -->\n      <div>\n        <div style=\"font-size:13px; font-weight:800; margin-bottom:8px; display:flex; justify-content:space-between; align-items:center;\">\n          <span>Registered Contestants</span>\n          <span id=\"manageCountBadge\" class=\"badge badge-primary\">0 Contestants</span>\n        </div>\n        <div class=\"table-container\" style=\"max-height:280px; overflow-y:auto;\">\n          <table class=\"data-table\">\n            <thead>\n              <tr>\n                <th style=\"width:70px;\">Ward #</th>\n                <th style=\"width:70px;\">Ballot #</th>\n                <th>Candidate Name</th>\n                <th>Party</th>\n                <th style=\"width:80px; text-align:center;\">Action</th>\n              </tr>\n            </thead>\n            <tbody id=\"manageCandidatesTableBody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n  </div>\n\n  <div id=\"toast\"></div>\n\n  <script>\n    let authToken = localStorage.getItem('salumber_auth_token') || '';\n    let masterData = { candidates: [], wards: [], roundVotes: {} };\n    let currentCandidates = [];\n    let activeEntryMode = 'booth'; // 'booth' or 'round'\n    let currentMappedWard = 1;\n\n    // Initialization\n    window.addEventListener('DOMContentLoaded', async () => {\n      checkAuthentication();\n    });\n\n    async function checkAuthentication() {\n      if (!authToken) {\n        showAuthModal();\n        return;\n      }\n      try {\n        const resp = await fetch('/api/auth/check', { headers: { 'X-Auth-Token': authToken } });\n        const res = await resp.json();\n        if (res.authenticated) {\n          hideAuthModal();\n          initApp();\n        } else {\n          showAuthModal();\n        }\n      } catch (e) {\n        showAuthModal();\n      }\n    }\n\n    function showAuthModal() {\n      document.getElementById('authModal').style.display = 'flex';\n      document.getElementById('loginPassword').focus();\n    }\n\n    function hideAuthModal() {\n      document.getElementById('authModal').style.display = 'none';\n    }\n\n    async function submitLogin() {\n      const pwd = document.getElementById('loginPassword').value.trim();\n      const errEl = document.getElementById('authError');\n      errEl.style.display = 'none';\n\n      if (!pwd) {\n        errEl.innerText = 'Please enter password!';\n        errEl.style.display = 'block';\n        return;\n      }\n\n      try {\n        const resp = await fetch('/api/auth/login', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ password: pwd })\n        });\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          authToken = res.token;\n          localStorage.setItem('salumber_auth_token', authToken);\n          hideAuthModal();\n          initApp();\n        } else {\n          errEl.innerText = res.detail || 'Invalid password!';\n          errEl.style.display = 'block';\n        }\n      } catch (e) {\n        errEl.innerText = 'Connection error: ' + e;\n        errEl.style.display = 'block';\n      }\n    }\n\n    function logout() {\n      localStorage.removeItem('salumber_auth_token');\n      authToken = '';\n      showAuthModal();\n    }\n\n    async function initApp() {\n      await loadMasterData();\n      populateBoothDropdown();\n      populateWardDropdown();\n      onCategoryChanged();\n      initWebSocket();\n    }\n\n    function initWebSocket() {\n      const loc = window.location;\n      const wsUrl = (loc.protocol === 'https:' ? 'wss://' : 'ws://') + loc.host + '/ws';\n      const ws = new WebSocket(wsUrl);\n      ws.onmessage = (event) => {\n        try {\n          const data = JSON.parse(event.data);\n          if (data.type === 'INITIAL_STATE' || data.type === 'FULL_UPDATE' || data.type === 'ROUND_UPDATE') {\n            loadMasterData();\n          }\n        } catch (e) {}\n      };\n      ws.onclose = () => { setTimeout(initWebSocket, 3000); };\n    }\n\n    async function loadMasterData() {\n      try {\n        const resp = await fetch('/api/all_candidates_master');\n        if (resp.ok) {\n          masterData = await resp.json();\n        }\n      } catch (e) {}\n    }\n\n    function switchNavTab(tab) {\n      document.querySelectorAll('.nav-tab-btn').forEach(b => b.classList.remove('active'));\n      document.querySelectorAll('section[id^=\"panel\"]').forEach(p => p.style.display = 'none');\n\n      if (tab === 'entry') {\n        document.getElementById('tabBtnEntry').classList.add('active');\n        document.getElementById('panelEntry').style.display = 'flex';\n        refreshEntryView();\n      } else if (tab === 'declare') {\n        document.getElementById('tabBtnDeclare').classList.add('active');\n        document.getElementById('panelDeclare').style.display = 'flex';\n        loadDeclareWardsTable();\n      } else if (tab === 'contestants') {\n        document.getElementById('tabBtnContestants').classList.add('active');\n        document.getElementById('panelContestants').style.display = 'flex';\n        loadManageBlockContestants();\n      }\n    }\n\n    // ENTRY MODE TOGGLE (BOOTH VS ROUND)\n    function toggleEntryMode(mode) {\n      activeEntryMode = mode;\n      document.getElementById('boothSelectorBox').style.display = mode === 'booth' ? 'grid' : 'none';\n      document.getElementById('roundSelectorBox').style.display = 'none';\n      refreshEntryView();\n    }\n\n    function onCategoryChanged() {\n      const cat = document.getElementById('entryCategory').value;\n      const blkGrp = document.getElementById('blockSelectGroup');\n      if (cat === 'PS') blkGrp.style.display = 'flex';\n      else blkGrp.style.display = 'none';\n\n      populateBoothDropdown();\n      populateWardDropdown();\n      refreshEntryView();\n    }\n\n    function onBlockChanged() {\n      populateBoothDropdown();\n      populateWardDropdown();\n      refreshEntryView();\n    }\n\n    const BLOCK_TOTAL_BOOTHS = {\n      'Geengla': 68,\n      'Semari': 69,\n      'Salumbar': 77,\n      'Lasadiya': 73,\n      'Sarada': 78,\n      'Jhallara': 83,\n      'Jaisamand': 84\n    };\n\n    function populateBoothDropdown() {\n      const cat = document.getElementById('entryCategory').value;\n      const blk = document.getElementById('entryBlock').value || 'Semari';\n      const maxB = cat === 'ZP' ? 522 : (BLOCK_TOTAL_BOOTHS[blk] || 70);\n\n      const inputBooth = document.getElementById('inputBoothNo');\n      inputBooth.max = maxB;\n      let curVal = parseInt(inputBooth.value) || 1;\n      if (curVal > maxB) {\n        curVal = 1;\n        inputBooth.value = 1;\n      }\n\n      const sel = document.getElementById('selectBoothDropdown');\n      sel.innerHTML = '';\n      for (let b = 1; b <= maxB; b++) {\n        const opt = document.createElement('option');\n        opt.value = b;\n        opt.textContent = `Polling Station #${b} of ${maxB} (${blk})`;\n        sel.appendChild(opt);\n      }\n      sel.value = curVal;\n    }\n\n    function populateWardDropdown() {\n      const cat = document.getElementById('entryCategory').value;\n      const maxW = cat === 'ZP' ? 21 : 15;\n      const sel = document.getElementById('entryWard');\n      sel.innerHTML = '';\n      for (let w = 1; w <= maxW; w++) {\n        const opt = document.createElement('option');\n        opt.value = w;\n        opt.textContent = `Ward ${w}`;\n        sel.appendChild(opt);\n      }\n    }\n\n    function onBoothInputChanged() {\n      const bno = parseInt(document.getElementById('inputBoothNo').value) || 1;\n      document.getElementById('selectBoothDropdown').value = bno;\n      refreshEntryView();\n    }\n\n    function onBoothDropdownChanged() {\n      const bno = document.getElementById('selectBoothDropdown').value;\n      document.getElementById('inputBoothNo').value = bno;\n      refreshEntryView();\n    }\n\n    function onWardRoundChanged() {\n      refreshEntryView();\n    }\n\n    function refreshEntryView() {\n      const cat = document.getElementById('entryCategory').value;\n      const blk = cat === 'ZP' ? 'Salumber ZP' : document.getElementById('entryBlock').value;\n\n      let targetWard = 1;\n      let roundKey = 'R1';\n\n      // Look up ward configuration (total booths & max rounds)\n      if (activeEntryMode === 'round') {\n        targetWard = parseInt(document.getElementById('entryWard').value) || 1;\n      } else {\n        const bno = parseInt(document.getElementById('inputBoothNo').value) || 1;\n        if (cat === 'PS') {\n          targetWard = Math.min(15, Math.max(1, Math.ceil(bno / 5)));\n        } else {\n          targetWard = Math.min(21, Math.max(1, Math.ceil(bno / 25)));\n        }\n      }\n\n      const wardInfo = masterData.wards.find(w => w.category === cat && w.block_name === blk && w.ward_no === targetWard);\n      const totalBooths = wardInfo ? (wardInfo.total_booths || (cat === 'ZP' ? 25 : 5)) : 5;\n      const tables = wardInfo ? (wardInfo.counting_tables || 5) : 5;\n      const maxRounds = Math.max(1, Math.ceil(totalBooths / (tables || 5)));\n\n      if (activeEntryMode === 'booth') {\n        const bno = parseInt(document.getElementById('inputBoothNo').value) || 1;\n        roundKey = `B${bno}`;\n        document.getElementById('boothInfoText').innerText = `\ud83d\udccd Polling Station #${bno} \u2022 ${blk} (Total Ward Booths: ${totalBooths})`;\n        document.getElementById('boothWardBadge').innerText = `Ward ${targetWard}`;\n      } else {\n        // Dynamically populate rounds dropdown based on actual max_rounds for this ward\n        const roundSelect = document.getElementById('entryRound');\n        const prevSelected = roundSelect.value || 'R1';\n        roundSelect.innerHTML = '';\n        for (let r = 1; r <= maxRounds; r++) {\n          const opt = document.createElement('option');\n          opt.value = `R${r}`;\n          opt.textContent = (r === maxRounds) ? `Round ${r} of ${maxRounds} (Final Round)` : `Round ${r} of ${maxRounds}`;\n          if (opt.value === prevSelected) opt.selected = true;\n          roundSelect.appendChild(opt);\n        }\n        if (!roundSelect.value) roundSelect.value = 'R1';\n        roundKey = roundSelect.value;\n\n        document.getElementById('boothInfoText').innerText = `\ud83d\udcd1 ${blk} Ward ${targetWard} \u2022 ${totalBooths} Booths \u2022 ${maxRounds} Rounds Total`;\n        document.getElementById('boothWardBadge').innerText = `${roundKey} of ${maxRounds}`;\n      }\n\n      currentMappedWard = targetWard;\n      loadCandidateInputs(cat, blk, targetWard, roundKey);\n    }\n\n    function loadCandidateInputs(cat, blk, wardNo, roundKey) {\n      currentCandidates = masterData.candidates.filter(c => c.category === cat && c.block_name === blk && c.ward_no === wardNo);\n      currentCandidates.sort((a, b) => (a.ballot_no || 999) - (b.ballot_no || 999));\n\n      const tbody = document.getElementById('candidatesTableBody');\n      tbody.innerHTML = '';\n\n      if (currentCandidates.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"6\" style=\"text-align:center; color:var(--text-dim); padding:20px;\">No contestants registered for Ward ${wardNo} yet. Use <strong>Contestants Manager</strong> to add.</td></tr>`;\n        return;\n      }\n\n      currentCandidates.forEach(cand => {\n        const cVotes = masterData.roundVotes[cand.id] || {};\n        \n        // Calculate cumulative previous votes\n        let prevSum = 0;\n        for (const [k, v] of Object.entries(cVotes)) {\n          if (k !== roundKey) prevSum += (v || 0);\n        }\n\n        const curVal = cVotes[roundKey] !== undefined ? cVotes[roundKey] : '';\n        const initialTotal = prevSum + (Number(curVal) || 0);\n\n        const tr = document.createElement('tr');\n        tr.innerHTML = `\n          <td style=\"font-weight:700; font-family:'Rajdhani',sans-serif; font-size:15px;\">#${cand.ballot_no || '-'}</td>\n          <td style=\"font-weight:700; font-size:14px;\">${cand.name_hindi}</td>\n          <td><span class=\"party-pill party-${cand.party || 'IND'}\">${cand.party || 'IND'}</span></td>\n          <td style=\"text-align:right;\">\n            <input type=\"number\" id=\"voteInput_${cand.id}\" class=\"vote-input\" value=\"${curVal}\" min=\"0\" placeholder=\"0\"\n              oninput=\"calcLiveTotal(${cand.id}, ${prevSum})\">\n          </td>\n          <td style=\"text-align:right; font-family:'Rajdhani',sans-serif; font-size:16px; font-weight:700; color:var(--text-dim);\" id=\"prevTotal_${cand.id}\">\n            ${prevSum}\n          </td>\n          <td style=\"text-align:right; font-family:'Rajdhani',sans-serif; font-size:18px; font-weight:800; color:var(--primary);\" id=\"liveTotal_${cand.id}\">\n            ${initialTotal}\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function calcLiveTotal(candId, prevSum) {\n      const inp = document.getElementById(`voteInput_${candId}`);\n      const val = parseInt(inp.value) || 0;\n      document.getElementById(`liveTotal_${candId}`).innerText = prevSum + val;\n    }\n\n    function clearCurrentInputs() {\n      currentCandidates.forEach(cand => {\n        const inp = document.getElementById(`voteInput_${cand.id}`);\n        if (inp) {\n          inp.value = '';\n          const prev = parseInt(document.getElementById(`prevTotal_${cand.id}`).innerText) || 0;\n          document.getElementById(`liveTotal_${cand.id}`).innerText = prev;\n        }\n      });\n    }\n\n    async function submitVotes() {\n      const cat = document.getElementById('entryCategory').value;\n      const blk = cat === 'ZP' ? 'Salumber ZP' : document.getElementById('entryBlock').value;\n      const wardNo = currentMappedWard;\n\n      let roundKey = 'R1';\n      if (activeEntryMode === 'booth') {\n        const bno = document.getElementById('inputBoothNo').value || 1;\n        roundKey = `B${bno}`;\n      } else {\n        roundKey = document.getElementById('entryRound').value || 'R1';\n      }\n\n      const votesMap = {};\n      let hasValue = false;\n      currentCandidates.forEach(cand => {\n        const inp = document.getElementById(`voteInput_${cand.id}`);\n        if (inp && inp.value.trim() !== '') {\n          votesMap[cand.id] = parseInt(inp.value.trim()) || 0;\n          hasValue = true;\n        }\n      });\n\n      if (!hasValue) {\n        alert('Please enter votes for at least one candidate before saving.');\n        return;\n      }\n\n      try {\n        const resp = await fetch('/api/save_votes', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-Auth-Token': authToken },\n          body: JSON.stringify({\n            category: cat,\n            block: blk,\n            ward_no: wardNo,\n            round_key: roundKey,\n            votes: votesMap\n          })\n        });\n\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          showToast(`\u2705 Saved votes for ${roundKey} (Ward ${wardNo})!`);\n          await loadMasterData();\n\n          // Auto-advance to next booth if in booth mode\n          if (activeEntryMode === 'booth') {\n            const nextB = (parseInt(document.getElementById('inputBoothNo').value) || 1) + 1;\n            document.getElementById('inputBoothNo').value = nextB;\n            document.getElementById('selectBoothDropdown').value = nextB;\n            refreshEntryView();\n          } else {\n            refreshEntryView();\n          }\n        } else {\n          alert('Error: ' + (res.detail || 'Could not save votes.'));\n        }\n      } catch (e) {\n        alert('Network connection error: ' + e);\n      }\n    }\n\n    // TAB 2: DECLARE WARD WINNER\n    function onDeclareScopeChanged() {\n      const cat = document.getElementById('declareCategory').value;\n      const blkGrp = document.getElementById('declareBlockGroup');\n      if (cat === 'PS') blkGrp.style.display = 'flex';\n      else blkGrp.style.display = 'none';\n      loadDeclareWardsTable();\n    }\n\n    function loadDeclareWardsTable() {\n      const cat = document.getElementById('declareCategory').value;\n      const blk = cat === 'ZP' ? 'Salumber ZP' : document.getElementById('declareBlock').value;\n      const maxW = cat === 'ZP' ? 21 : 15;\n\n      const tbody = document.getElementById('declareWardsTableBody');\n      tbody.innerHTML = '';\n\n      for (let w = 1; w <= maxW; w++) {\n        const wInfo = masterData.wards.find(x => x.category === cat && x.block_name === blk && x.ward_no === w);\n        const isDeclared = wInfo ? wInfo.status === 'DECLARED' : false;\n\n        const cands = masterData.candidates.filter(c => c.category === cat && c.block_name === blk && c.ward_no === w);\n        \n        // Count votes and active entries\n        const entryKeys = new Set();\n        const candTotals = cands.map(c => {\n          let sum = 0;\n          const vObj = masterData.roundVotes[c.id] || {};\n          for (const [k, v] of Object.entries(vObj)) {\n            if (v > 0) {\n              sum += v;\n              entryKeys.add(k);\n            }\n          }\n          return { ...c, totalVotes: sum };\n        });\n\n        candTotals.sort((a, b) => b.totalVotes - a.totalVotes);\n        const leader = candTotals[0];\n        const runnerUp = candTotals[1];\n        const hasVotes = leader && leader.totalVotes > 0;\n        const isTie = hasVotes && runnerUp && (leader.totalVotes === runnerUp.totalVotes);\n        const margin = isTie ? 0 : (leader && runnerUp ? (leader.totalVotes - runnerUp.totalVotes) : (leader?.totalVotes || 0));\n\n        const totalBooths = wInfo ? (wInfo.total_booths || 5) : 5;\n        const tables = wInfo ? (wInfo.counting_tables || 5) : 5;\n        const maxRounds = Math.max(1, Math.ceil(totalBooths / (tables || 5)));\n        const completedRounds = entryKeys.size;\n        const isComplete = (completedRounds >= maxRounds && maxRounds > 0);\n\n        let statusBadge = '';\n        let actionBtn = '';\n\n        if (isDeclared) {\n          statusBadge = '<span class=\"badge badge-success\">\u2713 DECLARED</span>';\n          actionBtn = `<button onclick=\"reopenWard('${cat}', '${blk}', ${w})\" class=\"btn btn-outline\" style=\"padding:4px 8px; font-size:11px; color:var(--warning);\">\ud83d\udd13 Reopen</button>`;\n        } else if (isTie) {\n          statusBadge = `<span class=\"badge\" style=\"background:#fef3c7; color:#b45309; border:1px solid #f59e0b; font-weight:800;\">\u2696\ufe0f TIED (${completedRounds}/${maxRounds} Rds)</span>`;\n          actionBtn = `<button onclick=\"resolveTiePrompt('${cat}', '${blk}', ${w}, '${leader.name_hindi.replace(/'/g, \"\\\\'\")}', '${runnerUp.name_hindi.replace(/'/g, \"\\\\'\")}', ${leader.totalVotes})\" class=\"btn\" style=\"padding:6px 12px; font-size:11px; background:#d97706; color:#ffffff; font-weight:700;\">\u2696\ufe0f Resolve Tie (Lot)</button>`;\n        } else if (isComplete && hasVotes) {\n          statusBadge = `<span class=\"badge badge-success\">\u2713 100% COMPLETE (${completedRounds}/${maxRounds} Rds)</span>`;\n          actionBtn = `<button onclick=\"declareWardWinner('${cat}', '${blk}', ${w})\" class=\"btn btn-primary\" style=\"padding:6px 14px; font-size:11px; background:#15803d; border-color:#15803d;\">\ud83c\udfc6 Declare Winner</button>`;\n        } else if (hasVotes) {\n          statusBadge = `<span class=\"badge badge-primary\">\u26a1 Round ${completedRounds} of ${maxRounds}</span>`;\n          actionBtn = `<button onclick=\"declareWardWinner('${cat}', '${blk}', ${w})\" class=\"btn btn-outline\" style=\"padding:4px 8px; font-size:11px;\">Declare Early</button>`;\n        } else {\n          statusBadge = `<span class=\"badge\" style=\"background:#f1f5f9; color:#64748b;\">\u23f3 Awaiting (0/${maxRounds})</span>`;\n          actionBtn = `<span style=\"font-size:11px; color:var(--text-dim);\">-</span>`;\n        }\n\n        let leaderNameHtml = '-';\n        let partyHtml = '-';\n        let marginHtml = '-';\n\n        if (isTie) {\n          leaderNameHtml = `<span style=\"color:#b45309; font-weight:800;\">\u2696\ufe0f TIED: ${leader.name_hindi} & ${runnerUp.name_hindi}</span>`;\n          partyHtml = `<span class=\"badge\" style=\"background:#fef3c7; color:#92400e; font-weight:700;\">TIED (${leader.party || 'IND'} / ${runnerUp.party || 'IND'})</span>`;\n          marginHtml = `<span style=\"color:#b45309; font-weight:800;\">0 (Tied)</span>`;\n        } else if (hasVotes) {\n          leaderNameHtml = leader.name_hindi;\n          partyHtml = `<span class=\"party-pill party-${leader.party || 'IND'}\">${leader.party || 'IND'}</span>`;\n          marginHtml = `<span style=\"color:var(--primary); font-weight:800;\">+${margin} votes</span>`;\n        }\n\n        const tr = document.createElement('tr');\n        if (isTie) tr.style.background = '#fffbeb';\n        tr.innerHTML = `\n          <td style=\"font-weight:700;\">Ward ${w}<br><span style=\"font-size:10px; color:var(--text-dim); font-weight:600;\">${totalBooths} booths</span></td>\n          <td style=\"font-weight:700;\">${leaderNameHtml}</td>\n          <td>${partyHtml}</td>\n          <td style=\"text-align:right; font-family:'Rajdhani',sans-serif; font-size:16px; font-weight:800;\">${leader?.totalVotes || 0}</td>\n          <td style=\"text-align:right; font-size:12px;\">${marginHtml}</td>\n          <td style=\"text-align:center;\">${statusBadge}</td>\n          <td style=\"text-align:center;\">${actionBtn}</td>\n        `;\n        tbody.appendChild(tr);\n      }\n    }\n\n        async function resetTestingData() {\n      if (!confirm(\"\u26a0\ufe0f RESET ALL TEST DATA?\\n\\nThis will permanently delete all entered votes and reset all declared wards back to 0 votes for testing.\\n\\nAre you sure you want to proceed?\")) {\n        return;\n      }\n      try {\n        const resp = await fetch('/api/reset_testing_data', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-Auth-Token': authToken }\n        });\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          alert(\"\u2713 All test votes have been reset to 0! All declared wards reopened.\");\n          clearCurrentInputs();\n          await loadMasterData();\n          refreshEntryView();\n          if (document.getElementById('panelDeclare').style.display !== 'none') {\n            loadDeclareWardsTable();\n          }\n        } else {\n          alert(res.detail || res.message || \"Failed to reset data\");\n        }\n      } catch (e) {\n        alert(\"Error resetting test data: \" + e.message);\n      }\n    }\n\n    async function declareWardWinner(cat, blk, wno) {\n      if (!confirm(`Officially DECLARE and finalize winner for ${cat} ${blk} Ward ${wno}?`)) return;\n\n      try {\n        const resp = await fetch('/api/declare_ward', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-Auth-Token': authToken },\n          body: JSON.stringify({ category: cat, block: blk, ward_no: wno })\n        });\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          showToast(`\ud83c\udfc6 Ward ${wno} Winner Declared!`);\n          await loadMasterData();\n          loadDeclareWardsTable();\n        } else {\n          alert('Error: ' + (res.detail || 'Could not declare ward.'));\n        }\n      } catch (e) {\n        alert('Network error: ' + e);\n      }\n    }\n\n    async function reopenWard(cat, blk, wno) {\n      if (!confirm(`Re-open Ward ${wno} for corrections?`)) return;\n\n      try {\n        const resp = await fetch('/api/reopen_ward', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-Auth-Token': authToken },\n          body: JSON.stringify({ category: cat, block: blk, ward_no: wno })\n        });\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          showToast(`\ud83d\udd13 Ward ${wno} reopened.`);\n          await loadMasterData();\n          loadDeclareWardsTable();\n        }\n      } catch (e) {\n        alert('Error: ' + e);\n      }\n    }\n\n    // TAB 3: CONTESTANTS MANAGER\n    function loadManageBlockContestants() {\n      const cat = document.getElementById('manageCategory').value;\n      const blkGrp = document.getElementById('manageBlockGroup');\n      if (cat === 'PS') blkGrp.style.display = 'flex';\n      else blkGrp.style.display = 'none';\n\n      const blk = cat === 'ZP' ? 'Salumber ZP' : document.getElementById('manageBlock').value;\n\n      const cands = masterData.candidates.filter(c => c.category === cat && c.block_name === blk);\n      cands.sort((a, b) => a.ward_no - b.ward_no || (a.ballot_no || 0) - (b.ballot_no || 0));\n\n      document.getElementById('manageCountBadge').innerText = `${cands.length} Contestants`;\n\n      const tbody = document.getElementById('manageCandidatesTableBody');\n      tbody.innerHTML = '';\n\n      if (cands.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"5\" style=\"text-align:center; color:var(--text-dim); padding:20px;\">No contestants registered for ${cat} ${blk} yet. Paste list from Excel above.</td></tr>`;\n      } else {\n        cands.forEach(c => {\n          const tr = document.createElement('tr');\n          tr.innerHTML = `\n            <td style=\"font-weight:700;\">W${c.ward_no}</td>\n            <td style=\"font-weight:700; font-family:'Rajdhani',sans-serif;\">#${c.ballot_no || '-'}</td>\n            <td style=\"font-weight:700;\">${c.name_hindi}</td>\n            <td><span class=\"party-pill party-${c.party || 'IND'}\">${c.party || 'IND'}</span></td>\n            <td style=\"text-align:center;\">\n              <button onclick=\"deleteContestant(${c.id}, '${c.name_hindi}')\" class=\"btn btn-outline\" style=\"color:var(--danger); border-color:#fca5a5; padding:4px 8px; font-size:11px;\">\n                \ud83d\uddd1\ufe0f Delete\n              </button>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      }\n    }\n\n    async function submitBulkImport() {\n      const cat = document.getElementById('manageCategory').value;\n      const blk = cat === 'ZP' ? 'Salumber ZP' : document.getElementById('manageBlock').value;\n      const rawText = document.getElementById('bulkImportText').value.trim();\n\n      if (!rawText) {\n        alert('Please paste candidate rows first.');\n        return;\n      }\n\n      try {\n        const resp = await fetch('/api/candidates/bulk_import', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-Auth-Token': authToken },\n          body: JSON.stringify({ category: cat, block: blk, raw_text: rawText })\n        });\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          showToast(`\ud83d\ude80 ${res.message}`);\n          document.getElementById('bulkImportText').value = '';\n          await loadMasterData();\n          loadManageBlockContestants();\n        } else {\n          alert('Error: ' + (res.detail || 'Could not import contestants.'));\n        }\n      } catch (e) {\n        alert('Network error: ' + e);\n      }\n    }\n\n    async function deleteContestant(cid, name) {\n      if (!confirm(`Delete contestant \"${name}\"?`)) return;\n\n      try {\n        const resp = await fetch('/api/candidates/delete', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-Auth-Token': authToken },\n          body: JSON.stringify({ candidate_id: cid })\n        });\n        const res = await resp.json();\n        if (resp.ok && res.status === 'success') {\n          showToast(`\u2713 Deleted candidate ${name}`);\n          await loadMasterData();\n          loadManageBlockContestants();\n        }\n      } catch (e) {\n        alert('Network error: ' + e);\n      }\n    }\n\n    function showToast(msg) {\n      const t = document.getElementById('toast');\n      t.innerText = msg;\n      t.style.display = 'block';\n      setTimeout(() => { t.style.display = 'none'; }, 3000);\n    }\n  </script>\n</body>\n</html>\n";
